def min_groups(w, n, prices):
    groups = []
    for i in range(n):
        group_price = prices[i]
        if group_price > w:
            return -1
        if group_price == w:
            groups.append([group_price])
            continue
        for j in range(i+1, n):
            group_price += prices[j]
            if group_price > w:
                break
            groups.append([prices[i], prices[j]])
            i = j
    return len(groups)

